//! Reading and writing the stack `.env` files, plus host defaults.

use std::collections::BTreeMap;
use std::fs;
use std::io;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};

pub type EnvMap = BTreeMap<String, String>;

const PREAMBLE: &str = "\
# Generated by churn — rerun the installer to update.
# Safe to edit by hand; keys churn doesn't manage are preserved on rerun.";

/// Repository root, overridable for tests and for running from a checkout.
pub fn root() -> PathBuf {
    match std::env::var_os("CHURN_ROOT") {
        Some(dir) => PathBuf::from(dir),
        None => PathBuf::from(env!("CARGO_MANIFEST_DIR")),
    }
}

pub fn read(path: &Path) -> EnvMap {
    let Ok(contents) = fs::read_to_string(path) else {
        return EnvMap::new();
    };
    contents
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty() && !line.starts_with('#') && line.contains('='))
        .filter_map(|line| {
            let (key, value) = line.split_once('=')?;
            Some((key.trim().to_string(), value.trim().to_string()))
        })
        .collect()
}

/// Write `managed` keys in order, keeping any unrelated keys from a previous run.
pub fn write_merged(path: &Path, managed: &[(&str, String)]) -> io::Result<()> {
    let existing = read(path);
    let extras: Vec<(&String, &String)> = existing
        .iter()
        .filter(|(key, _)| {
            !managed
                .iter()
                .any(|(managed_key, _)| managed_key == &key.as_str())
        })
        .collect();

    let mut out = String::from(PREAMBLE);
    out.push_str("\n\n");
    for (key, value) in managed {
        out.push_str(&format!("{key}={value}\n"));
    }
    if !extras.is_empty() {
        out.push_str("\n# preserved from previous file\n");
        for (key, value) in extras {
            out.push_str(&format!("{key}={value}\n"));
        }
    }

    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(path, out)
}

/// Owning uid/gid of the data directory, so containers can write to it.
pub fn owner(path: &Path) -> (u32, u32) {
    match fs::metadata(path) {
        Ok(meta) => (meta.uid(), meta.gid()),
        Err(_) => current_owner(),
    }
}

/// Fallback when the path does not exist yet: our own uid/gid from /proc.
fn current_owner() -> (u32, u32) {
    if let Ok(status) = fs::read_to_string("/proc/self/status")
        && let Some(line) = status.lines().find(|line| line.starts_with("Uid:"))
    {
        let ids: Vec<u32> = line
            .trim_start_matches("Uid:")
            .split_whitespace()
            .filter_map(|id| id.parse().ok())
            .collect();
        if ids.len() >= 2 {
            return (ids[0], ids[1]);
        }
    }
    (0, 0)
}

fn detect_tz() -> String {
    if let Ok(tz) = std::env::var("TZ")
        && !tz.trim().is_empty()
    {
        return tz;
    }
    if let Ok(contents) = fs::read_to_string("/etc/timezone") {
        let trimmed = contents.trim();
        if !trimmed.is_empty() {
            return trimmed.to_string();
        }
    }
    if let Ok(target) = fs::read_link("/etc/localtime")
        && let Some((_, zone)) = target.to_string_lossy().split_once("zoneinfo/")
    {
        return zone.to_string();
    }
    "UTC".to_string()
}

pub fn timezone() -> String {
    detect_tz()
}

/// Best-effort LAN address of this host.
///
/// Prowlarr (inside gluetun's namespace) and Sonarr/Radarr (in the server
/// stack) sit in different network namespaces, so they cannot use `localhost`
/// to reach each other. The host's LAN address works for both when the stacks
/// share a machine. `CHURN_HOST_IP` overrides detection.
pub fn host_ip() -> String {
    if let Ok(ip) = std::env::var("CHURN_HOST_IP") {
        let ip = ip.trim();
        if !ip.is_empty() {
            return ip.to_string();
        }
    }
    detect_host_ip().unwrap_or_else(|| "127.0.0.1".to_string())
}

/// Ask the kernel which source address it would use for an internet route.
/// Connecting a UDP socket sends no packets, so this is offline-safe.
fn detect_host_ip() -> Option<String> {
    let socket = std::net::UdpSocket::bind("0.0.0.0:0").ok()?;
    socket.connect("1.1.1.1:80").ok()?;
    let address = socket.local_addr().ok()?;
    let ip = address.ip();
    if ip.is_loopback() || ip.is_unspecified() {
        return None;
    }
    Some(ip.to_string())
}
